import React, { useEffect, useRef, useState } from 'react';
import './WaterLevel.css';

const WaterLevel = ({ waterLevel }) => {
  const waterRef = useRef(null);
  const [bubbleCount, setBubbleCount] = useState(0);
  const [aerationMode, setAerationMode] = useState(0); // 0: Вкл, 1: Выкл, 2: Авт

  const colors = {
    water: '#5D9CEC',
    waterSurface: '#7AB3FF',
    glass: 'rgba(255, 255, 255, 0.2)',
    glassBorder: '#E2E8F0',
    bubble: 'rgba(255, 255, 255, 0.4)',
    emptyTank: '#F7FAFC'
  };

  const statusConfig = {
    nodata: { 
      message: 'Нет данные', 
      color: '#EDF2F7', 
      text: '#4A5568' 
    },
    nowater: {
      message: 'Воды мало!',
      color: '#FFF5F5',
      text: '#C53030',
      animation: 'pulse 1.5s infinite'
    },
    normal: { 
      message: 'Воды достаточно', 
      color: '#F0FFF4', 
      text: '#2F855A' 
    }
  };

  const status = waterLevel === 1 ? 'normal' : waterLevel === 0 ? 'nowater' : 'nodata';

  useEffect(() => {
    if (!waterRef.current || waterLevel !== 1 || aerationMode !== 0) return;

    const container = waterRef.current;
    const createBubble = () => {
      const bubble = document.createElement('div');
      bubble.className = 'water-bubble';

      const size = Math.random() * 10 + 5;
      const left = Math.random() * 80 + 10;
      const delay = Math.random() * 3;

      bubble.style.cssText = `
        width: ${size}px;
        height: ${size}px;
        left: ${left}%;
        bottom: 0;
        animation-delay: ${delay}s;
        opacity: ${Math.random() * 0.5 + 0.3};
      `;

      container.appendChild(bubble);
      setBubbleCount(prev => prev + 1);

      setTimeout(() => {
        bubble.remove();
      }, 3000);
    };

    const bubbleInterval = setInterval(createBubble, 800);
    return () => clearInterval(bubbleInterval);
  }, [waterLevel, aerationMode]);

  const setAeration = (mode) => {
    setAerationMode(mode);
  };

  return (
    <div className="water-card">
      <div className="water-header">
        <h2 className="water-title">
          <span className="icon">💧</span>Вода в аквапонике
        </h2>
      </div>

      <div className="water-display-container">
        {waterLevel === 1 ? (
          <div className="water-tank">
            <div className="glass-container" ref={waterRef}>
              <div className="glass">
                <div 
                  className="water-fill" 
                  style={{
                    background: `linear-gradient(to bottom, ${colors.waterSurface}, ${colors.water})`,
                  }}
                >
                  <div className="water-shine"></div>
                </div>
                
                <div className="glass-stripes">
                  {[...Array(10)].map((_, i) => (
                    <div key={i} className="glass-stripe"></div>
                  ))}
                </div>
              </div> 
            </div>
            
            {/* Заголовок над кнопкой управления аэрацией */}
            <div className="aeration-title">Управление аэрацией</div>
            
            {/* Кнопка управления аэрацией с тремя состояниями и ползунком */}
            <div className="aeration-control">
              <div className="aeration-time-button">
                <div className="time-options">
                  <span 
                    className={aerationMode === 0 ? 'active' : ''}
                    onClick={() => setAeration(0)}
                  >
                    Вкл
                  </span>
                  <span 
                    className={aerationMode === 1 ? 'active' : ''}
                    onClick={() => setAeration(1)}
                  >
                    Выкл
                  </span>
                  <span 
                    className={aerationMode === 2 ? 'active' : ''}
                    onClick={() => setAeration(2)}
                  >
                    Авт
                  </span>
                </div>
                <div className={`time-slider mode-${aerationMode}`}></div>
              </div>
            </div>
          </div>
        ) : (
          <div className="empty-tank-visual">
            <div className="glass-container">
              <div className="glass empty">
                {waterLevel === null && <div className="no-data-icon">❓</div>}
              </div> 
            </div>
          </div>
        )}
      </div>

      <div className="water-footer">
        <div 
          className="status-message"
          style={{
            backgroundColor: statusConfig[status].color,
            color: statusConfig[status].text,
            animation: statusConfig[status]?.animation
          }}>
          {statusConfig[status].message}
        </div>
      </div>
    </div>
  );
};

export default WaterLevel;
